// 1. Define the Callback Signature (Interface)
typedef void (*EventCallback)(int source_id, const char* msg);

// 2. Host Function (The Core System)
void system_trigger(int id, const char* data, EventCallback cb) {
    if (cb) {
        cb(id, data); // Call the plugin/handler function
    }
}

// 3. Plugin Implementation (The Handler Function)
void logger_handler(int src, const char* m) {
    // Log the event
}

// 4. Usage Example
EventCallback handler_ptr = logger_handler;
system_trigger(101, "Data Ready", handler_ptr);

// Alternative: Passing directly
system_trigger(202, "Error", logger_handler);
